# Bubble sort: repeatedly swap adjacent out-of-order pairs.
def bubble_sort(a):
    a = a[:]                       # work on a copy
    n = len(a)
    for i in range(n):
        for j in range(n - 1 - i):     # last i are already in place
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
    return a

print(bubble_sort([5, 1, 4, 2, 8]))

